  Object.assign(fr, {"tr_voir_cle": "Afficher la clé privée (1 minute)", "tr_dest_changee": "L’adresse de réception a changé depuis la découverte : rien n’est envoyé. Vérifiez-la dans Réglages, puis « Envoyer maintenant ».", "tr_sources": "Les deux sources de la chaîne ne s’accordent pas : rien n’est envoyé. Changez la seconde source dans Réglages, ou attendez.", "tr_vide_encore": "Aucune sortie confirmée à prendre pour l’instant : nouvel essai dans 30 secondes.", "tr_compte": "Le trésor part vers votre adresse dans", "tr_envoyer_maintenant": "Envoyer maintenant", "tr_annuler": "Annuler", "tr_annule": "Envoi annulé. La clé reste en mémoire tant que GodGift Core est ouvert : « Envoyer maintenant » quand vous êtes prêt.", "tr_confirmer": "Frais élevés : {f} sats ({p} % du trésor, {t} sat/vB). GodGift Core ne les paie pas sans vous : vérifiez l’adresse, puis confirmez.", "tr_envoyer_frais": "Confirmer et envoyer", "tr_confirmee_attente": "Transaction confirmée au bloc {b} ({c} confirmation(s)) : GodGift Core veille jusqu’à 3.", "manif_change": "Le manifeste de la chasse a changé depuis votre première lecture : n’y croyez pas et signalez-le. GodGift Core n’ouvre rien d’autre que le premier.", "manif_invalide": "Le manifeste publié par la librairie est invalide (adresses mal formées) : il est ignoré.", "te_compte": "témoins ces 7 derniers jours (chiffre indicatif : les clés sont anonymes, ce sont les désaccords qui comptent)", "te_note": "Un témoin publie sur Nostr, après chaque vérification, un constat signé par une clé anonyme renouvelée chaque semaine : bloc, empreintes, résultat. Rien de personnel ; le relais voit seulement l’adresse IP de connexion."});
  Object.assign(en, {"tr_voir_cle": "Show the private key (1 minute)", "tr_dest_changee": "The receiving address changed since the discovery: nothing is sent. Check it in Settings, then « Send now ».", "tr_sources": "The two chain sources disagree: nothing is sent. Change the second source in Settings, or wait.", "tr_vide_encore": "No confirmed output to take for now: new try in 30 seconds.", "tr_compte": "The treasure leaves for your address in", "tr_envoyer_maintenant": "Send now", "tr_annuler": "Cancel", "tr_annule": "Sending cancelled. The key stays in memory while GodGift Core is open: « Send now » when you are ready.", "tr_confirmer": "High fees: {f} sats ({p} % of the treasure, {t} sat/vB). GodGift Core will not pay them without you: check the address, then confirm.", "tr_envoyer_frais": "Confirm and send", "tr_confirmee_attente": "Transaction confirmed in block {b} ({c} confirmation(s)): GodGift Core keeps watching until 3.", "manif_change": "The hunt's manifest changed since your first reading: do not trust it and report it. GodGift Core opens nothing but the first.", "manif_invalide": "The manifest published by the bookshop is invalid (malformed addresses): it is ignored.", "te_compte": "witnesses over the last 7 days (indicative figure: keys are anonymous, disagreements are what matter)", "te_note": "After each verification, a witness publishes on Nostr a report signed with an anonymous key renewed every week: block, fingerprints, result. Nothing personal; the relay only sees the connection's IP address."});
  Object.assign(es, {"tr_voir_cle": "Mostrar la clave privada (1 minuto)", "tr_dest_changee": "La dirección de recepción ha cambiado desde el hallazgo: no se envía nada. Compruébela en Ajustes y luego « Enviar ahora ».", "tr_sources": "Las dos fuentes de la cadena no coinciden: no se envía nada. Cambie la segunda fuente en Ajustes, o espere.", "tr_vide_encore": "Por ahora no hay ninguna salida confirmada que tomar: nuevo intento en 30 segundos.", "tr_compte": "El tesoro sale hacia su dirección en", "tr_envoyer_maintenant": "Enviar ahora", "tr_annuler": "Cancelar", "tr_annule": "Envío cancelado. La clave sigue en memoria mientras GodGift Core esté abierto: « Enviar ahora » cuando esté listo.", "tr_confirmer": "Comisiones elevadas: {f} sats ({p} % del tesoro, {t} sat/vB). GodGift Core no las paga sin usted: compruebe la dirección y confirme.", "tr_envoyer_frais": "Confirmar y enviar", "tr_confirmee_attente": "Transacción confirmada en el bloque {b} ({c} confirmación(es)): GodGift Core vigila hasta 3.", "manif_change": "El manifiesto de la búsqueda ha cambiado desde su primera lectura: no confíe en él y denúncielo. GodGift Core solo abre el primero.", "manif_invalide": "El manifiesto publicado por la librería no es válido (direcciones mal formadas): se ignora.", "te_compte": "testigos en los últimos 7 días (cifra indicativa: las claves son anónimas, lo que cuenta son los desacuerdos)", "te_note": "Tras cada verificación, un testigo publica en Nostr una constancia firmada con una clave anónima renovada cada semana: bloque, huellas, resultado. Nada personal; el relé solo ve la dirección IP de conexión."});
  Object.assign(de, {"tr_voir_cle": "Privaten Schlüssel anzeigen (1 Minute)", "tr_dest_changee": "Die Empfangsadresse hat sich seit dem Fund geändert: Nichts wird gesendet. Prüfen Sie sie in den Einstellungen, dann „Jetzt senden“.", "tr_sources": "Die beiden Quellen der Kette sind sich nicht einig: Nichts wird gesendet. Ändern Sie die zweite Quelle in den Einstellungen oder warten Sie.", "tr_vide_encore": "Im Moment keine bestätigte Ausgabe zu holen: neuer Versuch in 30 Sekunden.", "tr_compte": "Der Schatz geht an Ihre Adresse in", "tr_envoyer_maintenant": "Jetzt senden", "tr_annuler": "Abbrechen", "tr_annule": "Senden abgebrochen. Der Schlüssel bleibt im Speicher, solange GodGift Core geöffnet ist: „Jetzt senden“, wenn Sie bereit sind.", "tr_confirmer": "Hohe Gebühren: {f} sats ({p} % des Schatzes, {t} sat/vB). GodGift Core zahlt sie nicht ohne Sie: Prüfen Sie die Adresse und bestätigen Sie.", "tr_envoyer_frais": "Bestätigen und senden", "tr_confirmee_attente": "Transaktion in Block {b} bestätigt ({c} Bestätigung(en)): GodGift Core wacht bis 3.", "manif_change": "Das Manifest der Jagd hat sich seit Ihrer ersten Lesung geändert: Trauen Sie ihm nicht und melden Sie es. GodGift Core öffnet nur das erste.", "manif_invalide": "Das von der Buchhandlung veröffentlichte Manifest ist ungültig (fehlerhafte Adressen): Es wird ignoriert.", "te_compte": "Zeugen in den letzten 7 Tagen (Richtwert: Die Schlüssel sind anonym, es zählen die Unstimmigkeiten)", "te_note": "Nach jeder Prüfung veröffentlicht ein Zeuge auf Nostr einen Befund, signiert mit einem anonymen, wöchentlich erneuerten Schlüssel: Block, Fingerabdrücke, Ergebnis. Nichts Persönliches; das Relais sieht nur die IP-Adresse der Verbindung."});
  Object.assign(pt, {"tr_voir_cle": "Mostrar a chave privada (1 minuto)", "tr_dest_changee": "O endereço de receção mudou desde a descoberta: nada é enviado. Verifique-o em Definições e depois «Enviar agora».", "tr_sources": "As duas fontes da cadeia não concordam: nada é enviado. Mude a segunda fonte em Definições, ou aguarde.", "tr_vide_encore": "Por agora não há nenhuma saída confirmada a pegar: nova tentativa dentro de 30 segundos.", "tr_compte": "O tesouro parte para o seu endereço dentro de", "tr_envoyer_maintenant": "Enviar agora", "tr_annuler": "Cancelar", "tr_annule": "Envio cancelado. A chave fica em memória enquanto o GodGift Core estiver aberto: «Enviar agora» quando estiver pronto.", "tr_confirmer": "Taxas elevadas: {f} sats ({p} % do tesouro, {t} sat/vB). O GodGift Core não as paga sem si: verifique o endereço e confirme.", "tr_envoyer_frais": "Confirmar e enviar", "tr_confirmee_attente": "Transação confirmada no bloco {b} ({c} confirmação(ões)): o GodGift Core vigia até 3.", "manif_change": "O manifesto da caçada mudou desde a sua primeira leitura: não confie nele e denuncie-o. O GodGift Core só abre o primeiro.", "manif_invalide": "O manifesto publicado pela livraria é inválido (endereços mal formados): é ignorado.", "te_compte": "testemunhas nos últimos 7 dias (número indicativo: as chaves são anónimas, o que conta são os desacordos)", "te_note": "Após cada verificação, uma testemunha publica no Nostr um relatório assinado com uma chave anónima renovada todas as semanas: bloco, impressões digitais, resultado. Nada pessoal; o relé só vê o endereço IP da ligação."});
