  Object.assign(es, {"rec_date": "guardada el {d}", "rec_alerte": "Su dirección de recepción ha cambiado desde su última visita (guardada el {d}). Compruébela en la pantalla de su monedero: mientras no la reconozca, ningún tesoro sale solo.", "rec_reconnaitre": "Sí, es la dirección de mi monedero", "rec_err_sans_signature": "Pegue la firma de este mensaje, hecha por su monedero con esta dirección: sin ella, no se guarda nada.", "rec_err_type": "Este tipo de dirección aún no sabe firmar un mensaje (bc1p…, o script): elija una dirección bc1q…, 3… o 1… de su monedero.", "tr_rec_changee": "La llave está encontrada, pero su dirección de recepción ha cambiado desde su última visita: no sale nada hasta que la reconozca.", "tr_web_note": "En el teléfono, GodGift Core lo sirve un sitio web: lo verifica todo, y antes de cada envío de un tesoro le hace volver a escribir 16 caracteres de su dirección (dos trozos elegidos al azar, ocultos en pantalla); la aplicación instalada en un ordenador sigue siendo la vía más segura.", "web_sources": "(En el teléfono, solo se puede acceder a las fuentes previstas: mempool.space y blockstream.info.)", "coffret_solution_ko": "Este COFFRET contiene una solución: es el formato antiguo, rechazado desde el 2 de octubre de 2026. Se rechaza.", "coffret_doublon_ko": "Este COFFRET contiene dos veces el mismo candado: se rechaza.", "coffret_type_ko": "Este COFFRET contiene un candado de un tipo desconocido: se rechaza.", "coffret_incomplet_ko": "Este COFFRET está incompleto (se esperan dos enigmas, un grito y dos indicios por cofre): se rechaza.", "coffret_format_ko": "Este archivo no es un COFFRET bien formado de esta cacería: se rechaza.", "coffret_strophe_ko": "Un candado de este COFFRET no está cerrado en la ronda drand anunciada: se rechaza.", "coffret_signature_ko": "El manifiesto no está firmado por la dirección del autor fijada en este programa: no se abre nada.", "enigme_ecart": "La librería publica otro texto para este enigma: solo da fe el texto abierto aquí por drand (el COFFRET). Denúncielo.", "enigme_librairie_seule": "Texto publicado por la librería, aún no abierto aquí por el COFFRET.", "ouv_indice_1": "Indicio fuerte del cofre {n}", "ouv_indice_2": "Segundo indicio del cofre {n}", "v_indice_1": "Indicio fuerte", "v_indice_2": "Segundo indicio", "alea_faux": "Este aleatorio no es el que compromete el manifiesto grabado (su huella difiere): no es el verdadero grito. No se calcula nada.", "msg_forme": "forma no válida (fecha o texto): no es un mensaje de la Cueva", "msg_replie": "plegado: no se fíe (abrir para leer)", "sol_titre": "Solución publicada por el autor", "sol_tenu": "compromiso de la siembra cumplido", "sol_faux": "compromiso FALSO: estas palabras no son las comprometidas en la siembra", "sol_attente": "compromiso por verificar cuando el manifiesto de la cacería n.º {h} esté probado grabado", "sol_note": "GodGift Core nunca copia estas palabras en sus respuestas y no envía nada: la solución se verifica, no se juega.", "v_solutions_ok": "{n} solución(es) publicada(s): cada una cumple el compromiso grabado en la siembra.", "v_solutions_ko": "{f} de {n} solución(es) NO cumplen el compromiso grabado en la siembra.", "v_chasse": "Cacería n.º {n}", "v_chasse_avant": "a la espera de su manifiesto grabado", "v_chasse_ok": "manifiesto grabado, COFFRET conforme a la regla de la Cueva ({o} candados abiertos de {n}); {c} grito(s) conforme(s) en la cadena", "ann_retiree": "La cacería n.º {n} ya no se sigue: su anuncio ya no se verifica ({r}).", "roman_titre": "La novela: la huella grabada", "roman_intro": "En la publicación, el autor graba en la cadena la huella del archivo maestro de cada edición (AEDE:livre:fr o en). Prueba que este texto existía en esa fecha; no forma parte de la cacería.", "roman_aucune": "La huella grabada de la novela aparecerá aquí en la publicación.", "roman_deposer": "Deposite un archivo maestro EPUB para compararlo (la huella se calcula aquí, no se envía nada)", "roman_tx": "o verifique el grabado en la cadena (txid de la transacción)", "roman_ok": "Este archivo es exactamente la edición {l} cuya huella está grabada.", "roman_ko": "Este archivo no es aquel cuya huella está grabada (su huella: {h}…).", "roman_tx_ok": "Grabado confirmado en la cadena: AEDE:livre ({l}), el {d}.", "roman_tx_ko": "Esta transacción no graba, confirmada, la huella anunciada de la novela.", "roman_note": "La novela acompaña la cacería sin formar parte de ella: no contiene ningún enigma de la cacería, ni ninguna información útil para una respuesta que no se publique también gratuitamente. Su ejemplar numerado se verifica más arriba; solo el archivo maestro (guardado por el autor y el depositario) tiene la huella grabada."});
  Object.assign(de, {"rec_date": "gespeichert am {d}", "rec_alerte": "Ihre Empfangsadresse hat sich seit Ihrem letzten Besuch geändert (gespeichert am {d}). Prüfen Sie sie auf dem Bildschirm Ihrer Wallet: Solange Sie sie nicht bestätigen, geht kein Schatz von allein hinaus.", "rec_reconnaitre": "Ja, das ist die Adresse meiner Wallet", "rec_err_sans_signature": "Fügen Sie die Signatur dieser Nachricht ein, die Ihre Wallet mit dieser Adresse erstellt hat: Ohne sie wird nichts gespeichert.", "rec_err_type": "Dieser Adresstyp kann noch keine Nachricht signieren (bc1p… oder Skript): Wählen Sie eine Adresse bc1q…, 3… oder 1… Ihrer Wallet.", "tr_rec_changee": "Der Schlüssel ist gefunden, aber Ihre Empfangsadresse hat sich seit Ihrem letzten Besuch geändert: Nichts geht hinaus, bevor Sie sie bestätigen.", "tr_web_note": "Auf dem Telefon wird GodGift Core von einer Website ausgeliefert: Es prüft alles und lässt Sie vor jedem Versand eines Schatzes 16 Zeichen Ihrer Adresse erneut eintippen (zwei zufällig gewählte, auf dem Bildschirm verdeckte Stücke); die auf einem Computer installierte Anwendung bleibt der sicherste Weg.", "web_sources": "(Auf dem Telefon sind nur die vorgesehenen Quellen erreichbar: mempool.space und blockstream.info.)", "coffret_solution_ko": "Dieser COFFRET enthält eine Lösung: das alte Format, seit dem 2. Oktober 2026 abgelehnt. Er wird abgelehnt.", "coffret_doublon_ko": "Dieser COFFRET enthält dasselbe Schloss zweimal: Er wird abgelehnt.", "coffret_type_ko": "Dieser COFFRET enthält ein Schloss unbekannten Typs: Er wird abgelehnt.", "coffret_incomplet_ko": "Dieser COFFRET ist unvollständig (erwartet: zwei Rätsel, ein Ruf und zwei Hinweise pro Truhe): Er wird abgelehnt.", "coffret_format_ko": "Diese Datei ist kein wohlgeformter COFFRET dieser Jagd: Er wird abgelehnt.", "coffret_strophe_ko": "Ein Schloss dieses COFFRET ist nicht auf die angekündigte drand-Runde verschlossen: Er wird abgelehnt.", "coffret_signature_ko": "Das Manifest ist nicht von der in diesem Programm festgelegten Adresse des Autors signiert: Nichts öffnet sich.", "enigme_ecart": "Die Buchhandlung veröffentlicht für dieses Rätsel einen anderen Text: Maßgeblich ist nur der hier über drand geöffnete Text (der COFFRET). Melden Sie es.", "enigme_librairie_seule": "Von der Buchhandlung veröffentlichter Text, hier noch nicht durch den COFFRET geöffnet.", "ouv_indice_1": "Starker Hinweis der Truhe {n}", "ouv_indice_2": "Zweiter Hinweis der Truhe {n}", "v_indice_1": "Starker Hinweis", "v_indice_2": "Zweiter Hinweis", "alea_faux": "Dieser Zufallswert ist nicht der, den das gravierte Manifest festlegt (sein Fingerabdruck weicht ab): Es ist nicht der echte Ruf. Nichts wird berechnet.", "msg_forme": "ungültige Form (Datum oder Text): keine Nachricht aus der Höhle", "msg_replie": "eingeklappt: Vertrauen Sie ihm nicht (zum Lesen öffnen)", "sol_titre": "Vom Autor veröffentlichte Lösung", "sol_tenu": "Verpflichtung der Aussaat eingehalten", "sol_faux": "Verpflichtung FALSCH: Diese Wörter sind nicht die bei der Aussaat festgelegten", "sol_attente": "Verpflichtung wird geprüft, sobald das Manifest der Jagd Nr. {h} als graviert bewiesen ist", "sol_note": "GodGift Core übernimmt diese Wörter nie in Ihre Antworten und sendet nichts: Die Lösung wird geprüft, nicht gespielt.", "v_solutions_ok": "{n} veröffentlichte Lösung(en): Jede hält die bei der Aussaat gravierte Verpflichtung ein.", "v_solutions_ko": "{f} von {n} Lösung(en) halten die bei der Aussaat gravierte Verpflichtung NICHT ein.", "v_chasse": "Jagd Nr. {n}", "v_chasse_avant": "wartet auf sein graviertes Manifest", "v_chasse_ok": "Manifest graviert, COFFRET gemäß der Regel der Höhle ({o} von {n} Schlössern geöffnet); {c} korrekte(r) Ruf(e) auf der Kette", "ann_retiree": "Die Jagd Nr. {n} wird nicht mehr verfolgt: Ihre Ankündigung lässt sich nicht mehr prüfen ({r}).", "roman_titre": "Der Roman: der gravierte Fingerabdruck", "roman_intro": "Bei Erscheinen graviert der Autor den Fingerabdruck der Masterdatei jeder Ausgabe in die Kette (AEDE:livre:fr oder en). Er beweist, dass dieser Text an diesem Datum existierte; er ist kein Teil der Jagd.", "roman_aucune": "Der gravierte Fingerabdruck des Romans erscheint hier bei Erscheinen.", "roman_deposer": "Legen Sie eine EPUB-Masterdatei ab, um sie zu vergleichen (der Fingerabdruck wird hier berechnet, nichts wird gesendet)", "roman_tx": "oder prüfen Sie die Gravur auf der Kette (txid der Transaktion)", "roman_ok": "Diese Datei ist genau die Ausgabe {l}, deren Fingerabdruck graviert ist.", "roman_ko": "Diese Datei ist nicht die, deren Fingerabdruck graviert ist (ihr Fingerabdruck: {h}…).", "roman_tx_ok": "Gravur auf der Kette bestätigt: AEDE:livre ({l}), am {d}.", "roman_tx_ko": "Diese Transaktion graviert nicht, bestätigt, den angekündigten Fingerabdruck des Romans.", "roman_note": "Der Roman begleitet die Jagd, ohne Teil von ihr zu sein: Er enthält kein Rätsel der Jagd und keine für eine Antwort nützliche Information, die nicht auch kostenlos veröffentlicht wird. Ihr nummeriertes Exemplar wird weiter oben geprüft; nur die Masterdatei (beim Autor und beim Verwahrer) hat den gravierten Fingerabdruck."});
  Object.assign(pt, {"rec_date": "guardado a {d}", "rec_alerte": "O seu endereço de receção mudou desde a sua última visita (guardado a {d}). Verifique-o no ecrã da sua carteira: enquanto não o reconhecer, nenhum tesouro parte sozinho.", "rec_reconnaitre": "Sim, é o endereço da minha carteira", "rec_err_sans_signature": "Cole a assinatura desta mensagem, feita pela sua carteira com este endereço: sem ela, nada é guardado.", "rec_err_type": "Este tipo de endereço ainda não sabe assinar uma mensagem (bc1p…, ou script): escolha um endereço bc1q…, 3… ou 1… da sua carteira.", "tr_rec_changee": "A chave foi encontrada, mas o seu endereço de receção mudou desde a sua última visita: nada parte enquanto não o reconhecer.", "tr_web_note": "No telemóvel, o GodGift Core é servido por um site: verifica tudo e, antes de cada envio de um tesouro, faz-lhe voltar a escrever 16 caracteres do seu endereço (dois pedaços tirados ao acaso, ocultos no ecrã); a aplicação instalada num computador continua a ser a via mais segura.", "web_sources": "(No telemóvel, só as fontes previstas estão acessíveis: mempool.space e blockstream.info.)", "coffret_solution_ko": "Este COFFRET contém uma solução: é o formato antigo, recusado desde 2 de outubro de 2026. É recusado.", "coffret_doublon_ko": "Este COFFRET contém duas vezes o mesmo cadeado: é recusado.", "coffret_type_ko": "Este COFFRET contém um cadeado de um tipo desconhecido: é recusado.", "coffret_incomplet_ko": "Este COFFRET está incompleto (esperam-se dois enigmas, um grito e duas pistas por cofre): é recusado.", "coffret_format_ko": "Este ficheiro não é um COFFRET bem formado desta caçada: é recusado.", "coffret_strophe_ko": "Um cadeado deste COFFRET não está fechado na ronda drand anunciada: é recusado.", "coffret_signature_ko": "O manifesto não está assinado pelo endereço do autor fixado neste programa: nada se abre.", "enigme_ecart": "A livraria publica outro texto para este enigma: só faz fé o texto aberto aqui pelo drand (o COFFRET). Denuncie-o.", "enigme_librairie_seule": "Texto publicado pela livraria, ainda não aberto aqui pelo COFFRET.", "ouv_indice_1": "Pista forte do cofre {n}", "ouv_indice_2": "Segunda pista do cofre {n}", "v_indice_1": "Pista forte", "v_indice_2": "Segunda pista", "alea_faux": "Este aleatório não é o que o manifesto gravado compromete (a sua impressão difere): não é o verdadeiro grito. Nada é calculado.", "msg_forme": "forma inválida (data ou texto): não é uma mensagem da Caverna", "msg_replie": "dobrado: não confie (abrir para ler)", "sol_titre": "Solução publicada pelo autor", "sol_tenu": "compromisso da sementeira cumprido", "sol_faux": "compromisso FALSO: estas palavras não são as comprometidas na sementeira", "sol_attente": "compromisso a verificar quando o manifesto da caçada n.º {h} estiver provado gravado", "sol_note": "O GodGift Core nunca copia estas palavras para as suas respostas e não envia nada: a solução verifica-se, não se joga.", "v_solutions_ok": "{n} solução(ões) publicada(s): cada uma cumpre o compromisso gravado na sementeira.", "v_solutions_ko": "{f} de {n} solução(ões) NÃO cumprem o compromisso gravado na sementeira.", "v_chasse": "Caçada n.º {n}", "v_chasse_avant": "à espera do seu manifesto gravado", "v_chasse_ok": "manifesto gravado, COFFRET conforme à regra da Caverna ({o} cadeados abertos de {n}); {c} grito(s) conforme(s) na cadeia", "ann_retiree": "A caçada n.º {n} deixou de ser seguida: o seu anúncio já não se verifica ({r}).", "roman_titre": "O romance: a impressão gravada", "roman_intro": "Na publicação, o autor grava na cadeia a impressão do ficheiro mestre de cada edição (AEDE:livre:fr ou en). Prova que este texto existia nessa data; não faz parte da caçada.", "roman_aucune": "A impressão gravada do romance aparecerá aqui na publicação.", "roman_deposer": "Deposite um ficheiro mestre EPUB para o comparar (a impressão é calculada aqui, nada é enviado)", "roman_tx": "ou verifique a gravação na cadeia (txid da transação)", "roman_ok": "Este ficheiro é exatamente a edição {l} cuja impressão está gravada.", "roman_ko": "Este ficheiro não é aquele cuja impressão está gravada (a sua impressão: {h}…).", "roman_tx_ok": "Gravação confirmada na cadeia: AEDE:livre ({l}), a {d}.", "roman_tx_ko": "Esta transação não grava, confirmada, a impressão anunciada do romance.", "roman_note": "O romance acompanha a caçada sem fazer parte dela: não contém nenhum enigma da caçada, nem nenhuma informação útil para uma resposta que não seja também publicada gratuitamente. O seu exemplar numerado verifica-se mais acima; só o ficheiro mestre (guardado pelo autor e pelo depositário) tem a impressão gravada."});
