  Object.assign(en, {"tr_retape_morceau": "characters {a} to {b}", "fenetre_rechargee": "This window has been reloaded: it is no longer the dedicated window (its token lives only in memory and was erased with the page). Here, before each sending of a treasure, you will retype 16 characters of your receiving address. For the treasure to go by itself again, close this window and reopen GodGift Core from its icon.", "roman_mauvais_type": "This file is not an EPUB: drop a master EPUB file of the novel here, nothing else."});
